// Turns the SVG artwork in video/public/assets/svg into a typed tree that the
// Remotion templates can recolour and animate part by part (video/src/art/svg-art.tsx).
//   npm run svg:build        rewrite video/src/art/svg-docs.generated.ts
// The SVG files stay the source of truth; a test fails when the generated file is stale.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import type { SvgDoc, SvgNode } from "../video/src/art/svg-doc";

const here = path.dirname(fileURLToPath(import.meta.url));
export const SVG_DIR = path.join(here, "../video/public/assets/svg");
export const GENERATED_FILE = path.join(here, "../video/src/art/svg-docs.generated.ts");

const KEEP = new Set(["svg", "g", "defs", "path", "circle", "ellipse", "line", "rect", "use"]);
const TAG = /<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<(\/?)([A-Za-z][\w:-]*)((?:\s+[\w:.-]+\s*=\s*"[^"]*")*)\s*(\/?)>/g;
const ATTR = /([\w:.-]+)\s*=\s*"([^"]*)"/g;

function parse(xml: string, file: string): SvgNode {
  const root: SvgNode = { t: "#root", a: {}, c: [] };
  const stack: SvgNode[] = [root];
  // `title` carries text, which this parser skips: drop the whole element instead.
  const source = xml.replace(/<title>[\s\S]*?<\/title>/g, "");
  for (const m of source.matchAll(TAG)) {
    const [whole, closing, tag, attrs, selfClosing] = m;
    if (whole.startsWith("<!--") || whole.startsWith("<?")) continue;
    if (closing) {
      stack.pop();
      continue;
    }
    if (!KEEP.has(tag)) throw new Error(`${file}: unsupported element <${tag}>`);
    const a: Record<string, string> = {};
    for (const [, name, value] of attrs.matchAll(ATTR)) {
      if (name.startsWith("xmlns")) continue;
      a[name === "xlink:href" ? "href" : name] = value.replace(/\s+/g, " ").trim();
    }
    const node: SvgNode = { t: tag, a, c: [] };
    stack[stack.length - 1].c.push(node);
    if (!selfClosing) stack.push(node);
  }
  if (stack.length !== 1) throw new Error(`${file}: unbalanced tags`);
  const svg = root.c[0];
  if (!svg || svg.t !== "svg") throw new Error(`${file}: no <svg> root`);
  return svg;
}

export function buildDocs(): Record<string, SvgDoc> {
  const docs: Record<string, SvgDoc> = {};
  for (const dir of fs.readdirSync(SVG_DIR).sort()) {
    const full = path.join(SVG_DIR, dir);
    if (!fs.statSync(full).isDirectory()) continue;
    for (const file of fs.readdirSync(full).sort()) {
      if (!file.endsWith(".svg")) continue;
      const name = path.basename(file, ".svg").toLowerCase().replace(/[^a-z0-9]+/g, "_");
      const svg = parse(fs.readFileSync(path.join(full, file), "utf8"), `${dir}/${file}`);
      if (!svg.a.viewBox) throw new Error(`${dir}/${file}: missing viewBox`);
      if (docs[name]) throw new Error(`${dir}/${file}: duplicate name ${name}`);
      docs[name] = { viewBox: svg.a.viewBox, nodes: svg.c };
    }
  }
  return docs;
}

export function generatedSource(): string {
  const docs = buildDocs();
  return [
    "// Generated by scripts/build-svg-docs.ts from video/public/assets/svg. Do not edit:",
    "// change the SVG files and run `npm run svg:build`.",
    'import type { SvgDoc } from "./svg-doc";',
    "",
    `export const SVG_DOCS = ${JSON.stringify(docs, null, 1)} as const satisfies Record<string, SvgDoc>;`,
    "",
  ].join("\n");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  fs.writeFileSync(GENERATED_FILE, generatedSource());
  console.log(`${Object.keys(buildDocs()).length} SVG files -> ${path.relative(process.cwd(), GENERATED_FILE)}`);
}
